fn replace_chars(s: &[char], old: char, new: char) -> Vec<char> {
    s.iter()
        .map(|&c| if c == old { new } else { c })
        .collect()
}

fn main() {
    let input = vec!['a', 'b', 'c', 'a', 'd'];
    let old_char = 'a';
    let new_char = 'x';
    
    let result = replace_chars(&input, old_char, new_char);
    
    println!("{:?}", result); // Output: ['x', 'b', 'c', 'x', 'd']
}